require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/permissions.php';require_once __DIR__.'/includes/icons.php';auth_require_admin();$cfg=require __DIR__.'/config.php';$APP_USER=auth_user();$APP_ROLE='Administrador';$ACTIVE='estado_sistema';$db=clear_db();$tests=[];$start=microtime(true);$ok=$db->ok();$tests[]=['SQL Server',$ok,round((microtime(true)-$start)*1000,1),$ok?'Conectado':$db->error()];foreach(['FIXALARMS','BM_RTQP','PCP_RTQP','BES_RTQP','TECSS_RTQP'] as $o){$start=microtime(true);$n=$db->scalar("SELECT COUNT_BIG(*) FROM dbo.$o");$tests[]=[$o,$n!==null,round((microtime(true)-$start)*1000,1),$n===null?$db->error():number_format((float)$n,0,',','.') .' registros'];}$ACTIVE='estado_sistema';?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CLEAR · Estado del sistema</title><link rel="stylesheet" href="assets/css/app.css?v=3.0.0"><style>.sys{padding:0 22px}.sysgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.syscard{padding:18px;background:var(--surface);border:1px solid var(--line);border-radius:14px}.sysok{color:#15803d}.sysbad{color:#c52d26}.syscard b{font-size:20px}.sysmeta{margin-top:18px;background:var(--surface);border:1px solid var(--line);padding:18px;border-radius:14px}@media(max-width:900px){.sysgrid{grid-template-columns:1fr}}</style></head><body><div class="app"><?php include __DIR__.'/includes/sidebar.php';?><main class="main"><?php include __DIR__.'/includes/topbar.php';?><div class="page__head"><div><h1 class="page__title">Estado del sistema</h1><div class="page__sub">Diagnóstico de conectividad y rendimiento</div></div></div><section class="sys"><div class="sysgrid"><?php foreach($tests as $t):?><div class="syscard"><div class="<?php echo $t[1]?'sysok':'sysbad';?>"><?php echo $t[1]?'● Operativo':'● Error';?></div><h2><?php echo h($t[0]);?></h2><b><?php echo h($t[3]);?></b><div><?php echo $t[2];?> ms</div></div><?php endforeach;?></div><div class="sysmeta"><b>Servidor PHP</b><p>PHP <?php echo h(PHP_VERSION);?> · Memoria actual <?php echo round(memory_get_usage(true)/1048576,1);?> MB · Pico <?php echo round(memory_get_peak_usage(true)/1048576,1);?> MB</p></div></section></main></div><script src="assets/js/app.js"></script></body></html>